      <div className="flex shrink-0 items-center justify-between border-b border-zinc-200 p-4"><div className="flex items-center gap-3"><span className="rounded-lg bg-red-50 p-2 text-brand-600"><MessageSquare size={20}/></span><div><h2 className="text-sm font-semibold">Acadivo guide</h2><p className="mt-1 text-xs text-zinc-500">Company & product help</p></div></div><button onClick={close} aria-label="Close website guide" className="rounded-md p-2 text-zinc-500 hover:bg-zinc-100"><X size={18}/></button></div>
      <div ref={history} className="min-h-0 flex-1 overflow-y-auto p-4"><div role="log" aria-live="polite" aria-relevant="additions" className="space-y-4">{messages.map((message,index)=><div key={index} className={message.role === "user" ? "ml-8" : "mr-3"}><p className="mb-1 text-[10px] font-medium text-zinc-500">{message.role === "user" ? "You" : "Acadivo guide"}</p><div className={`whitespace-pre-wrap break-words rounded-lg px-3 py-3 text-sm leading-6 ${message.role === "user" ? "bg-zinc-900 text-white" : "border border-zinc-100 bg-zinc-50 text-zinc-700"}`}>{message.text}</div>{message.links && <div className="mt-2 flex flex-wrap gap-2">{message.links.map(link=><Link key={link.href} href={link.hr…459 tokens truncated…lose() : setOpen(true)} aria-expanded={open} aria-controls="website-guide" className="inline-flex items-center gap-2 rounded-full bg-brand-600 px-4 py-3 text-sm font-semibold text-white shadow-md hover:bg-brand-700"><MessageSquare size={19}/>{open ? "Close guide" : "Ask Acadivo"}</button></div>
